using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using SiteDesignPro.Core.Exchange;
using SiteDesignPro.Core.Geometry;
using SiteDesignPro.Core.Model;
using SiteDesignPro.Core.Samples;
using Xunit;

namespace SiteDesignPro.Core.Tests
{
    /// <summary>
    /// Reverse exchange: applies the change file produced by the SketchUp adapter (shared/samples/
    /// residential-complex-changes.json, generated by sketchup-site-design-pro/tests/support/make_sample_changes.rb)
    /// to the AutoCAD-side sample elements.
    /// </summary>
    public class ChangeSetTests
    {
        private static string SamplePath => Path.Combine(TestSupport.SharedDir, "samples", "residential-complex-changes.json");

        [Fact]
        public void SketchUpChangeFile_AppliesToDrawingElements()
        {
            ChangeSetDocument doc = ChangeSetReader.Read(SamplePath);
            (ProjectSettings settings, List<SiteElement> drawing) = SampleResidentialComplex.CreateDrawing(TestSupport.Catalog);
            Assert.Equal(settings.ProjectId, doc.ProjectId);
            Assert.Equal(3, doc.Changes.Count);
            var byLabel = drawing.ToDictionary(e => e.Label!, e => e);

            foreach (ElementChange c in doc.Changes)
            {
                SiteElement target = drawing.Single(e => e.Id == c.Id);
                (ChangeOutcome outcome, string msg) = ChangeSetReader.Apply(c, target, settings, TestSupport.Catalog, false);
                Assert.True(outcome == ChangeOutcome.Applied, c.Label + ": " + msg);
            }

            // moved light: package (60, 49.5, 0.15) m -> drawing millimetres including the project origin
            var light = (PointGeometry)byLabel["L-001"].Geometry;
            Assert.Equal((6550000.0 + 60.0) * 1000, light.Position.X, 3);
            Assert.Equal((4860000.0 + 49.5) * 1000, light.Position.Y, 3);
            Assert.Equal((520.0 + 0.15) * 1000, light.Position.Z, 3);
            Assert.Equal(2, byLabel["L-001"].Revision);

            Assert.Equal(Math.PI / 2, ((PointGeometry)byLabel["FB-002"].Geometry).Rotation, 6);
            Assert.Equal(2.2, byLabel["FB-001"].Parameters.Number("length"));
            Assert.True(byLabel["FB-001"].Parameters.Bool("armrests"));
        }

        [Fact]
        public void ChangedInAutoCadSinceExport_IsAConflictUnlessForced()
        {
            ChangeSetDocument doc = ChangeSetReader.Read(SamplePath);
            (ProjectSettings settings, List<SiteElement> drawing) = SampleResidentialComplex.CreateDrawing(TestSupport.Catalog);
            ElementChange c = doc.Changes.Single(x => x.Label == "FB-001");
            SiteElement bench = drawing.Single(e => e.Id == c.Id);
            bench.Parameters["seatHeight"] = ParamValue.Of(0.5); // edited in AutoCAD after the export
            Assert.Equal(ChangeOutcome.Conflict, ChangeSetReader.Apply(c, bench, settings, TestSupport.Catalog, false).Outcome);
            Assert.Equal(ChangeOutcome.Applied, ChangeSetReader.Apply(c, bench, settings, TestSupport.Catalog, true).Outcome);
            Assert.Equal(2.2, bench.Parameters.Number("length"));
        }

        [Fact]
        public void InvalidValuesAndForeignFilesAreRejected()
        {
            (ProjectSettings settings, List<SiteElement> drawing) = SampleResidentialComplex.CreateDrawing(TestSupport.Catalog);
            SiteElement bench = drawing.First(e => e.TypeId == "furniture.bench");
            var bad = new ElementChange { Id = bench.Id, TypeId = bench.TypeId };
            bad.Parameters["length"] = ParamValue.Of(500.0);
            Assert.Equal(ChangeOutcome.Invalid, ChangeSetReader.Apply(bad, bench, settings, TestSupport.Catalog, true).Outcome);
            var unknown = new ElementChange { Id = bench.Id, TypeId = bench.TypeId };
            unknown.Parameters["colour"] = ParamValue.Of("red");
            Assert.Equal(ChangeOutcome.Invalid, ChangeSetReader.Apply(unknown, bench, settings, TestSupport.Catalog, true).Outcome);
            SiteElement path = drawing.First(e => e.Geometry is PathGeometry);
            var move = new ElementChange { Id = path.Id, TypeId = path.TypeId, Position = new Vec3(1, 2, 3) };
            Assert.Equal(ChangeOutcome.Invalid, ChangeSetReader.Apply(move, path, settings, TestSupport.Catalog, true).Outcome);
            Assert.Throws<FormatException>(() => ChangeSetReader.Parse("{\"format\":\"something\"}"));
            Assert.Throws<FormatException>(() => ChangeSetReader.Parse("{\"format\":\"site-design-pro-changes\",\"schemaVersion\":\"2.0.0\"}"));
        }
    }
}
